WITH kept_keys AS (SELECT job_title, level FROM employees EXCEPT DISTINCT SELECT job_title, level FROM employees WHERE full_name LIKE '%Lee%'), kept_rows AS (SELECT s.* FROM employees s INNER JOIN kept_keys k ON s.job_title = k.job_title AND s.level = k.level) SELECT s.id, s.full_name, s.email, s.dept_id, s.manager_id, s.salary, (SELECT MAX(t2.salary) FROM employees t2 WHERE t2.dept_id = s.dept_id) AS max_employee_salary FROM kept_rows s ORDER BY max_employee_salary DESC NULLS LAST
